 function review(previous,known,day){const p=previous||{interval:0,successes:0,lapses:0};if(!known)return{due:addDays(day,1),interval:1,successes:0,lapses:whole(p.lapses)+1,lastDate:day,lastResult:false};if(p.lastDate===day&&p.lastResult)return{...p};const successes=whole(p.successes)+1;const interval=successes===1?1:successes===2?3:successes===3?7:Math.min(60,Math.max(14,Math.round((p.interval||7)*2)));return{due:addDays(day,interval),interval,successes,lapses:whole(p.lapses),lastDate:day,lastResult:true}}
 function weekStart(day){const dow=new Date(day+'T12:00:00Z').getUTCDay();return addDays(day,-((dow+6)%7))}
