 function weeklyRest(c,day){const start=weekStart(day),date=Object.keys(c.restDays||{}).find(d=>c.restDays[d]&&weekStart(d)===start)||'';return{start,end:addDays(start,6),date,available:!date}}
 function setRestDay(c,day,enabled=true){if(!validDate(day))return false;c.restDays=normalizeRestDays(c.restDays);if(enabled){const week=weekStart(day);for(const d of Object.keys(c.restDays))if(c.restDays[d]&&weekStart(d)===week)c.restDays[d]=false}c.restDays[day]=!!enabled;return true}
