 function tasks(minutes,day){const t=({60:[10,10,15,20,5],90:[15,15,20,30,10],120:[20,20,25,40,15]})[minutes]||[15,15,20,30,10];return['Revise 20 words','Review previous days’ words','Hanja book · chapters covered','Student book · lesson covered','Add new vocabulary'].map((name,i)=>({id:['review','yesterday','hanja','course','add-vocabulary'][i],name,minutes:t[i]}))}
 const courseParts=[['grammar-1','Grammar 1',1],['grammar-2','Grammar 2',5],['grammar-3','Grammar 3',9],['quiz-1','Quiz Yourself 1',2],['conversation-1','Conversation 1',3],['vocabulary-1','Vocabulary 1',4],['quiz-2','Quiz Yourself 2',6],['conversation-2','Conversation 2',7],['vocabulary-2','Vocabulary 2',8],['quiz-3','Quiz Yourself 3',10],['conversation-3','Conversation 3',11],['vocabulary-3','Vocabulary 3',12],['talk','Let’s Talk!',13],['word-web','Word Web',14],['culture','A Word on Culture',15]].map(([id,label,offset])=>({id,label,offset})).sort((a,b)=>a.offset-b.offset);
 const validUnit=u=>!!u&&Number.isInteger(u.chapter)&&u.chapter>=1&&u.chapter<=15&&courseParts.some(p=>p.id===u.part);
 const partBlock=id=>Number(id.split('-').at(-1))||1;
 const unitKey=(u,kind='text')=>u.part?'course-'+u.chapter+'-part-'+(kind==='exercises'?'quiz-'+partBlock(u.part):u.part):'course-'+u.chapter+'-block-'+u.block+'-'+kind;
 function nextCourse(c){if(c.books.course)return null;for(let chapter=1;chapter<=15;chapter++){if(c.books['course-'+chapter])continue;for(const part of courseParts)if(!c.books[unitKey({chapter,part:part.id})])return{chapter,part:part.id,block:partBlock(part.id)}}return null}
 function nextExercise(c,chapter){if(!chapter)return null;for(let n=1;n<=3;n++)if(!c.books[unitKey({chapter,part:'quiz-'+n})])return{chapter,part:'quiz-'+n,block:n};return null}
 function courseRange(u){if(!u)return null;if(u.part){const part=courseParts.find(p=>p.id===u.part);if(!part)return null;const page=17+(u.chapter-1)*16+part.offset;return{start:page,end:page}}return{start:17+(u.chapter-1)*16+(u.block-1)*4,end:20+(u.chapter-1)*16+(u.block-1)*4}}
 function makePlan(c,day,chapters){const before=Object.keys(c.dayPlans||{}).filter(d=>d<day).sort().at(-1),previous=before&&c.dayPlans[before],done=before?(c.sessions[before]?.tasks||[]):[],course=nextCourse(c),exercise=nextExercise(c,course?.chapter),same=previous&&JSON.stringify(course)===JSON.stringify(previous.course),sameExercise=previous&&JSON.stringify(exercise)===JSON.stringify(previous.exercise);return{hanja:chapters.filter(h=>!c.chapters[h.id]).slice(0,c.hanjaPace||1).map(h=>h.number),course,exercise,paragraph:same?previous.paragraph:'',exercises:sameExercise?previous.exercises:'',carry:previous?[...new Set([...(previous.carry||[]),...tasks(c.dailyMinutes,before).map(t=>t.id)])].filter(id=>!done.includes(id)):[]}}
 function recordCoursePart(c,day,chapter,part,completed=true){const unit={chapter,part};if(!validDate(day)||!validUnit(unit))return false;const wasComplete=!!c.books['course-'+chapter];c.books[unitKey(unit)]=completed;c.books['course-'+chapter]=completed&&(wasComplete||courseParts.every(p=>c.books[unitKey({chapter,part:p.id})]));const session=c.sessions[day]||{minutes:0,tasks:[],note:''};session.coveredParts=(session.coveredParts||[]).filter(u=>u.chapter!==chapter||u.part!==part);if(completed)session.coveredParts.push(unit);c.sessions[day]=session;return true;}
 function recordCoveredChapter(c,day,type,chapter){if(!validDate(day)||!['hanja','course'].includes(type)||!Number.isInteger(chapter)||chapter<1||chapter>(type==='hanja'?26:15))return false;const session=c.sessions[day]||{minutes:0,tasks:[],note:''},key=type==='hanja'?'coveredHanja':'coveredCourse';session[key]=[...new Set([...(session[key]||[]),chapter])].sort((a,b)=>a-b);c.sessions[day]=session;if(type==='hanja')c.chapters['chapter-'+chapter]=true;else setCourseChapter(c,chapter,true);return true;}
 function setCourseChapter(c,chapter,completed){c.books['course-'+chapter]=completed;for(const part of courseParts)c.books[unitKey({chapter,part:part.id})]=completed;if(!completed)for(let block=1;block<=4;block++)for(const kind of ['text','exercises'])c.books[unitKey({chapter,block},kind)]=false;}
 function completeTask(c,p,id,checked){if(id==='hanja')for(const n of p.hanja)c.chapters['chapter-'+n]=checked;const u=id==='course'?p.course:id==='exercises'?(p.exercise||p.course&&{chapter:p.course.chapter,part:'quiz-'+partBlock(p.course.part||'grammar-1')}):null;if(u?.part){c.books[unitKey(u)]=checked;c.books['course-'+u.chapter]=checked&&courseParts.every(part=>c.books[unitKey({chapter:u.chapter,part:part.id})]);}else if(p.course&&['course','exercises'].includes(id)){const kind=id==='course'?'text':'exercises';c.books[unitKey(p.course,kind)]=checked;}}
 function refreshPlan(c,p,chapters,done=[]){if(!done.includes('hanja'))p.hanja=chapters.filter(h=>!c.chapters[h.id]).slice(0,c.hanjaPace||1).map(h=>h.number);if(!done.includes('course')||!validUnit(p.course)){const next=nextCourse(c);if(JSON.stringify(next)!==JSON.stringify(p.course)){p.paragraph=''}p.course=next}if(!done.includes('exercises')||!validUnit(p.exercise)){const next=nextExercise(c,p.course?.chapter);if(JSON.stringify(next)!==JSON.stringify(p.exercise))p.exercises='';p.exercise=next;}return p}
 const nextChapter=(chapters,completed)=>chapters.find(c=>!completed[c.id]);
 const bundles=[1,2,3].map(n=>({id:'bundle-'+n,label:`Grammar ${n} + Quiz ${n} + Conversation ${n} + Vocabulary ${n}`,parts:[`grammar-${n}`,`quiz-${n}`,`conversation-${n}`,`vocabulary-${n}`]}));
