 function completeBundle(c,day,chapter,id,completed=true){const b=bundles.find(b=>b.id===id);if(!b)return false;for(const part of b.parts)recordCoursePart(c,day,chapter,part,completed);return true}
 function yesterdayWords(words,day){return words.filter(w=>!w.hanjaRef&&w.studyRef?.kind==='vocabulary'&&w.studyRef.date===addDays(day,-1))}
 function previousWords(words,day){const eligible=words.filter(w=>!w.deleted&&!w.hanjaRef&&w.studyRef?.kind==='vocabulary'&&validDate(w.studyRef.date)&&w.studyRef.date<day),last=eligible.map(w=>w.studyRef.date).sort().at(-1);return last?eligible.filter(w=>w.studyRef.date===last):[]}
 function upgradePreviousWords(c,words,day){if(c.previousWordsVersion===1)return false;const prior=previousWords(words,day);if(prior.length&&prior[0].studyRef.date!==addDays(day,-1)&&c.sessions[day])c.sessions[day].tasks=c.sessions[day].tasks.filter(id=>id!=='yesterday');c.previousWordsVersion=1;return true}
 function dailyReview(c,words,day,history={},limit=20,random=Math.random){limit=Math.min(20,Math.max(1,limit));const byId=new Map(words.filter(w=>!w.deleted&&!w.hanjaRef&&w.studyRef?.kind!=='grammar').map(w=>[w.id,w]));if(c.reviewBatches[day])return c.reviewBatches[day].map(id=>byId.get(id)).filter(Boolean);const recent=new Set(previousWords(words,day).map(w=>w.id)),unique=new Map();for(const w of byId.values()){if(recent.has(w.id)||w.studyRef?.date>=day)continue;const key=w.korean?.normalize('NFKC').replace(/\s+/g,'').toLowerCase()||w.id;if(!unique.has(key))unique.set(key,w)}const pool=[...unique.values()];for(let i=pool.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}const picks=pool.slice(0,limit);c.reviewBatches[day]=picks.map(w=>w.id);return picks;}
 function readiness(c,level){const target=level===3?140:170,recent=[...c.mocks].sort((a,b)=>a.date.localeCompare(b.date)).slice(-3),score=m=>m.listening+m.reading+m.writing;const checks=[{id:'course',label:'Finish the structured intermediate course',done:!!c.books.course},{id:'guide',label:'Finish the TOPIK II question-type guide',done:!!c.books.guide},{id:'writing'+level,label:level===3?'Practise questions 51–53 with feedback':'Practise all four writing tasks with feedback',done:!!c.skills['writing'+level]},{id:'mock'+level,label:`Three recent timed PBT mocks at ${target}+/300`,done:recent.length===3&&recent.every(m=>score(m)>=target)}];return{level,officialThreshold:level===3?120:150,practiceTarget:target,checks,percent:Math.round(checks.filter(c=>c.done).length/checks.length*100)}}
 return{base,normalize,weekStart,normalizeRestDays,weeklyRest,setRestDay,seedWeeklyRest,previousWords,upgradePreviousWords,validDate,addDays,review,streak,tasks,nextChapter,readiness,nextCourse,courseRange,makePlan,completeTask,refreshPlan,unitKey,setCourseChapter,recordCoveredChapter,courseParts,validUnit,partBlock,recordCoursePart,nextExercise,dailyReview,bundles,bundleFor,completeBundle,yesterdayWords};
